// Combination domain for a bound effect parameter. AddDb: contributions sum in
// dB on the base. Multiply: commutative product on the base (neutral 1).
// AddLogHz / AddLogQ / AddLogTime: base scaled by 2^(sum of
// contributions), an octave-linear shift. None: binding is unsupported,
// so attaching one is refused (never implicit last-writer-wins).
enum class EffectParamCombine : std::uint32_t {
    AddDb,
    Multiply,
    AddLogHz,
    AddLogQ,
    None,
    AddLogTime,
};

// Unit of a parameter's authored value (tooling / observability).
enum class EffectParamUnit : std::uint32_t {
    Db,
    Linear,
    Hz,
    Q,
    Ms,
    Ratio,
};

// Sentinel clampMax: the resolved value is bounded STRICTLY BELOW the Nyquist
// frequency (0.5 * sampleRate), resolved at reduction time (not a fixed literal),
// so a composed frequency always satisfies the released validator's freq <
// nyquist rule when it reaches the audio thread.
inline constexpr float kEffectParamClampNyquist = -1.0f;

// Sentinel clampMin: the resolved value's lower bound is the smallest positive
// float (std::numeric_limits<float>::denorm_min()), resolved at reduction time. It
// expresses the released validator's open "value > 0" rule for frequency and Q
// EXACTLY -- a numeric floor here would be tighter than the validator and would
// suppress a valid low composed value. Chosen far below any real parameter floor
// so it can never collide with an authored numeric clampMin.
inline constexpr float kEffectParamClampStrictlyPositive = -1.0e30f;

// Sentinel clampMax: the resolved value's upper bound is the largest float
// strictly below 1.0f (std::nextafter(1.0f, 0.0f)). It expresses an open
// "value < 1" validator bound without tightening the accepted domain.
inline constexpr float kEffectParamClampStrictlyBelowOne = -1.0e29f;

static_assert(kEffectParamClampNyquist !=
                  kEffectParamClampStrictlyPositive &&
              kEffectParamClampNyquist !=
                  kEffectParamClampStrictlyBelowOne &&
              kEffectParamClampStrictlyPositive !=
                  kEffectParamClampStrictlyBelowOne,
              "effect parameter clamp sentinels must be unique");

// Metadata authority for one effect parameter (see effect_registry.json). The
// binding resolver reads combine/neutral/clamp to compose a parameter's
// contributions on its base and clamp the result before it reaches the audio
// thread; a parameter's authored direct value is the base.
struct EffectParamMeta {
    const char* name;
    EffectParamUnit unit;
    EffectParamCombine combine;
    float neutral; // binding-combine identity, not an authored default
    float clampMin; // strictly-positive sentinel => denorm_min()
    float clampMax; // Nyquist/open-one sentinel => concrete bound
    bool supportsTransition;
    bool dynamicControlSafe;
};

