// Resolves an effect-type id to its registry row, or nullptr for an unknown
// type (the caller treats that as an empty/refused effect, unchanged from the
// hand-written dispatch's default cases).
inline const EffectRegistryRow* FindEffectRow(std::uint32_t type) {
    for (std::uint32_t i = 0; i < kEffectRegistryRowCount; ++i) {
        if (kEffectRegistry[i].effectType == type) {
            return &kEffectRegistry[i];
        }
    }
    return nullptr;
}

// Resolves (effect type, parameter index) to its parameter metadata, or nullptr
// when the type is unknown or the index is outside the type's parameter space.
inline const EffectParamMeta* FindEffectParamMeta(std::uint32_t type,
                                                  std::uint32_t paramIndex) {
    const EffectRegistryRow* row = FindEffectRow(type);
    if (row == nullptr || paramIndex >= row->paramCount) {
        return nullptr;
    }
    return &row->params[paramIndex];
}

// Consistency pins: the row count must fit the fixed VnSnapshot per-type
// stats table, the table's effect-type value must equal the public ABI enum,
// the rows must be in effect-type order, each row's parameter count must equal
// the public per-type constant, and every pooled state type must be no more
// aligned than the pool's storage guarantees. A mismatch is a compile error,
// never a silent registry bug. (Completeness against the public effect-id set
// is cross-checked by the generator against Harken.h.)
static_assert(kEffectRegistryRowCount == 5,
              "effect registry row count drift");
static_assert(kEffectRegistryRowCount <= VN_MAX_EFFECT_TYPE_STATS,
              "the registry must fit the fixed VnSnapshot per-type stats table (VN_MAX_EFFECT_TYPE_STATS rows)");
static_assert(VN_EFFECT_FEEDBACK_DELAY == 0,
              "effect-type ABI value drift: feedbackDelay");
